"use client"

import React, {
    useEffect,
    useState,
} from "react"
import {
    Button,
    Input,
    Pagination,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    BookmarkCard,
} from "./BookmarkCard"
import { pathConfig } from "@/resources/path"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard } from "@/components/blocks/cards/SurfaceListCard"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { Cluster } from "@/components/frames/Cluster"
import { SAVED_CONTENTS_PAGE_SIZE, useQuerySavedContentsSwr } from "@/hooks/swr/api/graphql/queries/useQuerySavedContentsSwr"

/**
 * Bookmark page ΓÇö a searchable, paginated library of the viewer's saved contents.
 * Follows the list-surface anatomy: a primary search input balanced by the result
 * count, one {@link SurfaceListCard} of saved-lesson rows, and a left-aligned
 * {@link Pagination} (hidden on a single page). Search + paging are resolved
 * server-side (`savedContents(skip, take, search)`); typing snaps back to page 1.
 * Data states go through {@link AsyncContent}. A truly-empty library (never
 * bookmarked, no active search) renders {@link EmptyState} with a "browse
 * courses" CTA instead of a dead end; a zero-match search stays inline with
 * {@link AsyncContentEmpty} so the search box remains reachable. Mounted by
 * `/profile/bookmarks`.
 */
export const BookmarksPage = () => {
    const t = useTranslations()
    const router = useRouter()

    // search input (debounced ΓåÆ server-side title filter) + 1-based page
    const [search, setSearch] = useState("")
    const [debounced, setDebounced] = useState("")
    const [page, setPage] = useState(1)

    // debounce keystrokes before hitting the server
    useEffect(() => {
        const timer = setTimeout(() => setDebounced(search.trim()), 300)
        return () => clearTimeout(timer)
    }, [search])

    // a new search shrinks the list ΓÇö snap back to the first page
    useEffect(() => {
        setPage(1)
    }, [debounced])

    const {
        data,
        isLoading,
        error,
        mutate,
    } = useQuerySavedContentsSwr(page, debounced)

    const contents = data?.contents ?? []
    const count = data?.count ?? 0
    const totalPages = Math.ceil(count / SAVED_CONTENTS_PAGE_SIZE)
    const pageNumbers = Array.from({ length: totalPages }, (_unused, index) => index + 1)

    const skeletonRows = [0, 1, 2, 3, 4].map((row) => () => (
        <Box key={row} principle="card-padding" className="p-4"
            explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
            <StackH
                gap={4}
                align="center"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                    () => (
                        <StackV
                            gap={3}
                            principle="sibling-stack"
                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                            classNames={["flex-1"]}
                            items={[
                                () => <Skeleton className="h-4 w-1/2 rounded-medium" />,
                                () => <Skeleton className="h-3 w-1/3 rounded-medium" />,
                            ]}
                        />
                    ),
                ]}
            />
        </Box>
    ))

    const listBodyItems = [
        () => (
            <Cluster
                gap={4}
                justify="between"
                align="center"
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (
                        <TextField className="w-full @app-sm:max-w-sm">
                            <Input
                                type="search"
                                aria-label={t("bookmarks.searchPlaceholder")}
                                placeholder={t("bookmarks.searchPlaceholder")}
                                value={search}
                                onChange={(event) => setSearch(event.target.value)}
                            />
                        </TextField>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted" className="shrink-0">
                            {t("bookmarks.found", { count })}
                        </Typography>
                    ),
                ]}
            />
        ),
        () => (
            contents.length === 0 ? (
                <AsyncContentEmpty title={t("bookmarks.noMatch")} />
            ) : (
                <>
                    <SurfaceListCard>
                        {contents.map((content) => (
                            <BookmarkCard key={content.id} content={content} />
                        ))}
                    </SurfaceListCard>

                    {totalPages > 1 ? (
                        <Pagination
                            aria-label={t("common.pagination.navAria")}
                            className="justify-start"
                            size="sm"
                        >
                            <Pagination.Content className="flex flex-wrap justify-start gap-2" data-principle="flex-action">
                                <Pagination.Item>
                                    <Pagination.Previous
                                        aria-label={t("common.pagination.previous")}
                                        isDisabled={page <= 1}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                        onPress={() => setPage((current) => Math.max(1, current - 1))}
                                    >
                                        <Pagination.PreviousIcon />
                                    </Pagination.Previous>
                                </Pagination.Item>
                                {pageNumbers.map((pageNumber) => (
                                    <Pagination.Item key={pageNumber}>
                                        <Pagination.Link
                                            isActive={pageNumber === page}
                                            className="cursor-pointer rounded-medium transition-colors hover:bg-default data-[active=true]:hover:bg-accent"
                                            onPress={() => setPage(pageNumber)}
                                        >
                                            {pageNumber}
                                        </Pagination.Link>
                                    </Pagination.Item>
                                ))}
                                <Pagination.Item>
                                    <Pagination.Next
                                        aria-label={t("common.pagination.next")}
                                        isDisabled={page >= totalPages}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                        onPress={() => setPage((current) => Math.min(totalPages, current + 1))}
                                    >
                                        <Pagination.NextIcon />
                                    </Pagination.Next>
                                </Pagination.Item>
                            </Pagination.Content>
                        </Pagination>
                    ) : null}
                </>
            )
        ),
    ]

    return (
        <Box identity={{ tier: "page", component: "BookmarksPage" }} principle="center-measure" className="mx-auto max-w-4xl"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
            <Box principle="page-pad" className="p-6"
                explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                <div className="flex flex-col gap-10">
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("bookmarks.heading")} />}
                        title={t("bookmarks.heading")}
                        description={t("bookmarks.subtitle")}
                    />
                    <AsyncContent
                        isLoading={isLoading && !data}
                        skeleton={(
                            <SurfaceListCard>
                                {skeletonRows.map((Row, index) => (
                                    <Row key={index} />
                                ))}
                            </SurfaceListCard>
                        )}
                        error={error}
                        errorContent={{
                            title: t("bookmarks.errorTitle"),
                            onRetry: () => { void mutate() },
                            retryLabel: t("dashboard.retry"),
                        }}
                    >
                        {!debounced && count === 0 ? (
                            <EmptyState
                                title={t("bookmarks.empty")}
                                description={t("bookmarks.emptyHint")}
                                action={() => (
                                    <Button
                                        variant="primary"
                                        onPress={() => router.push(pathConfig().locale().course().build())}
                                    >
                                        {`${t("dashboard.browseCourses")} ΓåÆ`}
                                    </Button>
                                )}
                            />
                        ) : (
                            <StackV
                                gap={4}
                                principle="sibling-stack"
                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                items={listBodyItems}
                            />
                        )}
                    </AsyncContent>
                </div>
            </Box>
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    Button,
    Card,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { CheckListCard, CheckListItem } from "@/components/blocks/cards/CheckListCard"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Community membership feature container.
 *
 * A single-product purchase surface ($5/month equivalent): premium tech blog,
 * private community, course discount, recruitment exposure. Opening the shared
 * payment overlay with {@link PaymentFlow.Membership} lets the user pick a
 * gateway, which then runs `purchaseMembership` + redirects to checkout.
 * Mounted by the `/profile/membership` route. `"use client"` because it reads
 * the payment overlay singleton and routes.
 */
export const MembershipPage = () => {
    const t = useTranslations()
    // shared payment modal ΓÇö opening it with the membership flow runs the purchase
    const { open: openPaymentModal } = usePaymentOverlayState()


    /** Perk rows shown under the price ΓÇö each is a translated benefit line. */
    const perks = useMemo(
        () => [
            t("membership.perks.blog"),
            t("membership.perks.community"),
            t("membership.perks.discount"),
            t("membership.perks.recruitment"),
        ],
        [
            t,
        ],
    )

    /** Open the shared payment modal for the membership flow. */
    const onSubscribe = useCallback(
        () => {
            // hand the membership flow to the modal ΓÇö it creates the checkout
            // with whichever payment method the user picks, then redirects
            openPaymentModal({
                flow: PaymentFlow.Membership,
            })
        },
        [
            openPaymentModal,
        ],
    )

    const cardItems = [
        () => (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                items={[
                    () => (
                        <Typography type="h5" weight="semibold">
                            {t("membership.card.title")}
                        </Typography>
                    ),
                    () => (
                        <Typography type="body-sm" color="muted">
                            {t("membership.card.desc")}
                        </Typography>
                    ),
                ]}
            />
        ),
        () => (
            <div className="flex flex-col gap-0">
                <StackH
                    gap={3}
                    align="end"
                    principle="value-row"
                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                    items={[
                        () => (
                            <Typography type="h3" weight="bold">
                                {t("membership.price")}
                            </Typography>
                        ),
                        () => (
                            <Typography type="body-sm" color="muted" className="pb-1">
                                {t("membership.priceHint")}
                            </Typography>
                        ),
                    ]}
                />
                <Typography type="body-xs" color="muted">
                    {t("membership.priceApprox")}
                </Typography>
            </div>
        ),
        () => (
            <CheckListCard>
                {perks.map((perk) => (
                    <CheckListItem key={perk}>
                        <Typography type="body-sm">{perk}</Typography>
                    </CheckListItem>
                ))}
            </CheckListCard>
        ),
        () => (
            <Button
                variant="primary"
                fullWidth
                onPress={onSubscribe}
            >
                {t("membership.cta")}
            </Button>
        ),
    ]

    return (
        <Box identity={{ tier: "page", component: "MembershipPage" }} principle="center-measure" className="mx-auto max-w-2xl"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
            <Box principle="page-pad" className="p-6"
                explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                <div className="flex flex-col gap-10">
                    <PageHeader
                        breadcrumb={<SettingsBreadcrumb current={t("membership.title")} />}
                        title={t("membership.title")}
                        description={t("membership.subtitle")}
                    />
                    <Card className="flex flex-col">
                        <Card.Content>
                            <StackV
                                gap={6}
                                principle="sibling-stack"
                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                items={cardItems}
                            />
                        </Card.Content>
                    </Card>
                </div>
            </Box>
        </Box>
    )
}

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { CaretRightIcon, GearSixIcon, SparkleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Breadcrumbs, type BreadcrumbItem } from "@/components/atoms/navigation/Breadcrumbs"
import { Chip } from "@/components/atoms/chips/Chip"

import { Typography } from "@/components/atoms/text/Typography"
import {
    SurfaceCard,
    SurfaceCardAccordion,
    type SurfaceCardAccordionItem,
} from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { ListRow } from "@/components/composites/lists/List"
import { PageHeader } from "@/components/composites/layout/Page"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { Container } from "@/components/frames/Container"
import { StackH, StackV } from "@/components/frames/Stack"
import { SplitWorkspace } from "@/components/frames/SplitWorkspace"
import {
    ContentRelatedList,
    type ContentRelatedItem,
} from "@/components/blocks/learn/ContentRelatedList"
import {
    SubmissionScoreCard,
    type AiModelCategory,
} from "@/components/blocks/learn/SubmissionScoreCard"

/**
 * `PersonalProjectTaskPage` ΓÇö the screen to solve one personal-project task. A
 * screen owns a list of functions. Split workspace: a reading column that swaps
 * per task (task identity, the locked-preview banner, the authored brief or the
 * legacy rubric/implementation guides, and related lessons) beside a
 * persistent, sticky act column (repo URL, the settings-drawer trigger,
 * evaluate/secondary actions, and the latest graded result). Two columns
 * composed with `SplitWorkspace`: a `min-w-0 flex-1` reading column beside a
 * `shrink-0 w-[360px]` sticky aside, stacked on mobile/tablet ΓåÆ
 * `@app-xl:flex-row` on desktop. The grading-settings drawer content is not
 * built ΓÇö `onOpenSettings` is a chrome trigger only.
 *
 * PRESENTATIONAL ΓÇö every input arrives as a prop; this twin owns no data of
 * its own, so `index.tsx` IS the presentational file (no separate connected
 * wrapper, no `component.tsx` split) ΓÇö mirrors `MindMapPage`'s convention.
 *
 * Emits its own identity (`data-tier="page"` / `data-component="PersonalProjectTaskPage"`)
 * unconditionally, handed down to the root `Container` via its `identity` prop
 * (see `frames/_identity.ts`) rather than drawn on a wrapper `div` of its own
 * (`tiers/block.md` BLOCK-2: a page never draws a shape of its own) ΓÇö same as
 * `split.md`'s "Identity is data-tier + data-component" section. The
 * breadcrumb sits in a `StackH inline` (shrink-to-content sizing) rather
 * than a raw `div`.
 */

/** One personal-project schema-v1 evaluation criterion ΓÇö the legacy rubric row. */
export interface PersonalProjectTaskLegacyCriterionItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** The criterion sentence itself. */
    text: string
    /** Points this criterion is worth. */
    score: number
    /** Optional grading hint, markdown. Omit ΓåÆ the panel shows a plain "no hint" line. */
    hint?: string
}

/** One legacy per-language implementation guide (schema-v1 tasks with no authored brief). */
export interface PersonalProjectTaskLegacyCodeImplementationItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Target language label, e.g. "TypeScript". */
    lang: string
    /** How to approach the task in this language, markdown. */
    guide: string
    /** A worked example, markdown. */
    example: string
}

/** The task identity this screen reads about. */
export interface PersonalProjectTaskPageTask {
    /** Task title. */
    title: string
    /** One-paragraph summary of what the task asks for. */
    description?: string
}

/** The schema-v2 authored brief for this task. */
export interface PersonalProjectTaskPageBrief {
    /** The brief itself, markdown, already resolved to the active language/locale. */
    body: string
}

/** Cost/quality tier + model byline data for a graded submission ΓÇö see {@link SubmissionScoreCard}. */
export interface PersonalProjectSubmissionResult {
    /** Points earned on the latest graded attempt. */
    score: number
    /** Points the attempt was scored out of. */
    maxScore?: number
    /** Whether this score cleared the pass bar. */
    isPassing: boolean
    /** The pass bar itself, in points. */
    passScore?: number
    /** A short line of grader feedback. */
    shortFeedback?: string
    /** The model that produced this grade. */
    gradedByModel?: string
    /** Cost/quality tier of {@link gradedByModel}. */
    modelCategory?: AiModelCategory
    /** Relative time since grading, already localized. */
    timeAgo?: string
}

/** Everything the persistent, sticky act column needs ΓÇö the project-level submission loop. */
export interface PersonalProjectTaskSubmissionPanelProps {
    /** The GitHub repo URL as typed so far. */
    repoUrl: string
    /** Fired as the learner types the repo URL. */
    onRepoUrlChange: (value: string) => void
    /** Validation message for the repo URL field. Set ΓåÆ the field shows invalid. */
    repoUrlError?: string
    /** Grading language summary shown in the settings row, e.g. "TypeScript". */
    settingsLangLabel: string
    /** Grading branch summary shown in the settings row, e.g. "main". */
    settingsBranch: string
    /** Fired when the settings summary row is pressed ΓÇö chrome trigger only, see file header. */
    onOpenSettings: () => void
    /** Fired to submit the current repo for AI evaluation. */
    onEvaluate: () => void
    /** `true` ΓåÆ the evaluate CTA shows its own spinner and blocks further presses. */
    isEvaluatePending?: boolean
    /** `true` ΓåÆ the evaluate CTA is disabled (the caller's own combined business rule ΓÇö locked, syncing, ΓÇª). */
    isEvaluateDisabled?: boolean
    /** `true` ΓåÆ at least one attempt exists, so the secondary actions unlock and the CTA reads "Re-evaluate". */
    hasAttempts?: boolean
    /** Fired to open the full feedback/result page. */
    onOpenFeedbackDetails: () => void
    /** Fired to open the attempts history drawer. */
    onOpenAttempts: () => void
    /** The latest graded attempt. Present ΓåÆ the score card renders; omit ΓåÆ nothing has been graded yet. */
    result?: PersonalProjectSubmissionResult
}

/** Props for {@link PersonalProjectTaskPage}. */
export interface PersonalProjectTaskPageProps {
    /** Breadcrumb trail as DATA ΓÇö `PageHeader` builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<BreadcrumbItem>
    /** The task being read/solved. */
    task: PersonalProjectTaskPageTask
    /**
     * `true` ΓåÆ this task is not yet unlocked for the learner (previewing ahead
     * of their current milestone position). Shows the warning banner; nothing
     * else in the reading column changes shape.
     */
    isLocked?: boolean
    /** The schema-v2 authored brief. */
    brief: PersonalProjectTaskPageBrief
    /** Schema-v1 legacy rubric ΓÇö only present on tasks with no authored brief. */
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    /** Schema-v1 legacy per-language implementation guides ΓÇö only present alongside {@link legacyCriteria}. */
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    /** Lessons related to this task's subject, auto-derived by the caller from its title/description. */
    relatedItems: Array<ContentRelatedItem>
    /** Section label for {@link relatedItems}, e.g. "You might want to read". */
    relatedLabel: string
    /** Everything the persistent, sticky act column needs. */
    submissionPanelProps: PersonalProjectTaskSubmissionPanelProps
    /**
     * `true` ΓåÆ every part that can mirror itself does. Flows down into the
     * reading column's composed parts and the act column's fields/buttons/score
     * card (┬º12c) rather than a parallel skeleton tree built here.
     */
    isSkeleton?: boolean
}

/** Skeleton placeholder count for the legacy accordions while real data hasn't landed yet. */
const LEGACY_SKELETON_ROWS = 2

/** `ListRow.leading` for the grading-settings summary row ΓÇö a gear icon, hidden while skeleton. */
const SettingsLeading = ({ isSkeleton }: SkeletonProps) =>
    isSkeleton ? null : <GearSixIcon aria-hidden focusable="false" className="size-4" />

/** `ListRow.trailing` for the grading-settings summary row ΓÇö the disclosure chevron. */
const SettingsChevron = () => <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4" />

/** One markdown body at the `compact` measure the legacy accordion panels use. */
const legacyMarkdown = (body: string) => (
    <MarkdownContent source={body} measure="compact" />
)

/** One legacy code-implementation accordion panel body: guide, then a worked example. */
const legacyCodeBody = (item: PersonalProjectTaskLegacyCodeImplementationItem) => {
    const guideSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Guide" />
            {legacyMarkdown(item.guide)}
        </>
    )
    const exampleSection = (
        <>
            <Typography size="xs" weight="medium" color="muted" text="Example" />
            {legacyMarkdown(item.example)}
        </>
    )
    return (
        <StackV
            gap={4}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
            items={[
                () => <StackV gap={2} items={[() => guideSection]} />,
                () => <StackV gap={2} items={[() => exampleSection]} />,
            ]}
        />
    )
}

/**
 * The reading column: task identity (`PageHeader`) + the locked banner + the
 * brief itself + the legacy rubric/implementation guides + related lessons.
 * A private render helper (see file header for why this is not a separate
 * storied component), not an anatomy node of its own.
 */
const readingColumn = (props: {
    breadcrumbItems?: Array<BreadcrumbItem>
    task: PersonalProjectTaskPageTask
    isLocked: boolean
    brief: PersonalProjectTaskPageBrief
    legacyCriteria?: Array<PersonalProjectTaskLegacyCriterionItem>
    legacyCodeImplementations?: Array<PersonalProjectTaskLegacyCodeImplementationItem>
    relatedItems: Array<ContentRelatedItem>
    relatedLabel: string
    isSkeleton: boolean
}) => {
    const {
        breadcrumbItems,
        task,
        isLocked,
        brief,
        legacyCriteria,
        legacyCodeImplementations,
        relatedItems,
        relatedLabel,
        isSkeleton,
    } = props

    const hasLegacyCriteria = (legacyCriteria?.length ?? 0) > 0
    const hasLegacyCode = (legacyCodeImplementations?.length ?? 0) > 0
    const showLegacy = isSkeleton || hasLegacyCriteria || hasLegacyCode
    // Schema-v2 tasks always carry an authored brief; schema-v1 (legacy) tasks
    // hand this screen an empty `body` and rely on the legacy section instead
    // (mirrors `src`'s `TaskBrief` self-hiding when `briefs.length === 0`).
    const showBrief = isSkeleton || brief.body.trim().length > 0

    const criteriaItems: Array<SurfaceCardAccordionItem> = hasLegacyCriteria
        ? (legacyCriteria ?? []).map((item, index) => ({
            id: item.key,
            title: `${index + 1}. ${item.text}`,
            titleEnd: () => <Chip tone="accent" text={`${item.score} points`} />,
            body: () => (
                item.hint
                    ? legacyMarkdown(item.hint)
                    : <Typography size="sm" color="muted"
                        isItalic text="No grading hint yet" />
            ),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `criteria-skeleton-${index}`, title: "", body: () => null }))
            : []

    const codeItems: Array<SurfaceCardAccordionItem> = hasLegacyCode
        ? (legacyCodeImplementations ?? []).map((item) => ({
            id: item.key,
            title: item.lang,
            body: () => legacyCodeBody(item),
        }))
        : isSkeleton
            ? Array.from({ length: LEGACY_SKELETON_ROWS }, (_unused, index) => ({ id: `code-skeleton-${index}`, title: "", body: () => null }))
            : []

    const legacyAccordions = (
        <>
            {hasLegacyCriteria || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={criteriaItems}
                    allowsMultipleExpanded
                    isSkeleton={isSkeleton}


                />
            ) : null}
            {hasLegacyCode || isSkeleton ? (
                <SurfaceCardAccordion
                    variant="nested"
                    items={codeItems}
